<?php
$connection = db();
function catalog_upload_image(): ?string {
    if (empty($_FILES['image']['name'])) return null;
    $types = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp'];
    $mime = mime_content_type($_FILES['image']['tmp_name']);
    if ($_FILES['image']['error'] !== UPLOAD_ERR_OK || $_FILES['image']['size'] > 3 * 1024 * 1024 || !isset($types[$mime])) throw new RuntimeException('Use a JPG, PNG, or WEBP image under 3 MB.');
    $name = bin2hex(random_bytes(12)) . '.' . $types[$mime];
    if (!move_uploaded_file($_FILES['image']['tmp_name'], __DIR__ . '/../assets/images/products/' . $name)) throw new RuntimeException('The product image could not be saved.');
    return 'assets/images/products/' . $name;
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = $_POST['action'] ?? '';
    try {
        if ($action === 'category') { $name=trim((string)($_POST['category_name']??'')); $slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-')); if($name===''||$slug==='') throw new RuntimeException('Enter a category name.'); $statement=$connection->prepare('INSERT INTO categories (name,slug) VALUES (?,?)');$statement->bind_param('ss',$name,$slug);$statement->execute(); flash('success','Category added.'); }
        elseif ($action === 'product') { $id=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT);$name=trim((string)($_POST['name']??''));$sku=trim((string)($_POST['sku']??''));$category=filter_input(INPUT_POST,'category_id',FILTER_VALIDATE_INT);$description=trim((string)($_POST['short_description']??''));$price=filter_input(INPUT_POST,'price',FILTER_VALIDATE_FLOAT);$stock=filter_input(INPUT_POST,'stock_quantity',FILTER_VALIDATE_INT);$reorder=filter_input(INPUT_POST,'reorder_level',FILTER_VALIDATE_INT);$status=$_POST['status']??'active';$featured=isset($_POST['featured'])?1:0;if($name===''||$sku===''||!$category||$description===''||$price===false||$price<0||$stock===false||$stock<0||$reorder===false||$reorder<0||!in_array($status,['active','draft','out_of_stock'],true)) throw new RuntimeException('Check product name, SKU, price, quantities, and status.');$image=catalog_upload_image();if($id){if($image){$statement=$connection->prepare('UPDATE products SET category_id=?,name=?,sku=?,short_description=?,image_path=?,price=?,stock_quantity=?,reorder_level=?,featured=?,status=? WHERE id=?');$statement->bind_param('issssdiiisi',$category,$name,$sku,$description,$image,$price,$stock,$reorder,$featured,$status,$id);}else{$statement=$connection->prepare('UPDATE products SET category_id=?,name=?,sku=?,short_description=?,price=?,stock_quantity=?,reorder_level=?,featured=?,status=? WHERE id=?');$statement->bind_param('isssdiiisi',$category,$name,$sku,$description,$price,$stock,$reorder,$featured,$status,$id);}$statement->execute();flash('success','Product updated.');}else{$statement=$connection->prepare('INSERT INTO products (category_id,name,sku,short_description,image_path,price,stock_quantity,reorder_level,featured,status) VALUES (?,?,?,?,?,?,?,?,?,?)');$statement->bind_param('issssdiiis',$category,$name,$sku,$description,$image,$price,$stock,$reorder,$featured,$status);$statement->execute();flash('success','Product added.');}}
        elseif ($action === 'stock') { $id=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT);$quantity=filter_input(INPUT_POST,'adjustment',FILTER_VALIDATE_INT);$note=substr(trim((string)($_POST['note']??'Manual stock adjustment')),0,255);if(!$id||$quantity===false||$quantity===0) throw new RuntimeException('Enter a valid stock adjustment.');$connection->begin_transaction();$statement=$connection->prepare('SELECT stock_quantity FROM products WHERE id=? FOR UPDATE');$statement->bind_param('i',$id);$statement->execute();$product=$statement->get_result()->fetch_assoc();if(!$product||(int)$product['stock_quantity']+$quantity<0) throw new RuntimeException('This adjustment would make stock negative.');$statement=$connection->prepare('UPDATE products SET stock_quantity=stock_quantity+? WHERE id=?');$statement->bind_param('ii',$quantity,$id);$statement->execute();$type=$quantity>0?'in':'adjustment';$statement=$connection->prepare('INSERT INTO stock_movements (product_id,movement_type,quantity,notes) VALUES (?,?,?,?)');$statement->bind_param('isis',$id,$type,$quantity,$note);$statement->execute();$connection->commit();flash('success','Stock updated and recorded.');}
        elseif ($action === 'deactivate') { $id=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT);if(!$id) throw new RuntimeException('Invalid product.');$statement=$connection->prepare("UPDATE products SET status='draft', featured=0 WHERE id=?");$statement->bind_param('i',$id);$statement->execute();flash('success','Product removed from the public store.'); }
    } catch (Throwable $exception) { if($connection->errno===0){} try{$connection->rollback();}catch(Throwable $ignored){} error_log('Sammy Tech catalog: '.$exception->getMessage());flash('error',$exception->getMessage()); }
    header('Location: catalog.php'); exit;
}
$categories=$connection->query('SELECT * FROM categories ORDER BY name')->fetch_all(MYSQLI_ASSOC);$products=$connection->query('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.updated_at DESC')->fetch_all(MYSQLI_ASSOC);$success=flash('success');$error=flash('error');echo '<style>header>a b{display:none!important}header>a:before{content:"";display:inline-block;vertical-align:middle;width:40px;height:40px;margin-right:9px;border-radius:50%;background:#07182e url("../assets/images/sammy-tech-logo.jpeg") center/cover no-repeat;box-shadow:0 0 0 2px #0ea5e9}</style>';
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catalog | Sammy Tech</title><link rel="stylesheet" href="../assets/css/catalog-manage.css"></head><body><header><a href="index.php"><b>ST</b> Sammy Tech</a><nav><a href="index.php">Dashboard</a><a class="active" href="catalog.php">Catalog</a><a href="reports.php">Reports</a><a href="../index.php" target="_blank">Storefront</a></nav></header><main><div class="title"><div><p>CATALOG MANAGEMENT</p><h1>Products, stock, and pricing.</h1></div><a href="#product-form">+ Add product</a></div><?php if($success):?><div class="flash success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><div class="catalog-grid"><section class="card" id="product-form"><h2>Add or edit product</h2><p class="helper">Use the edit button beside a product to load its details here.</p><form method="post" enctype="multipart/form-data" id="product-editor"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="product"><input type="hidden" name="product_id" id="product_id"><label>Name<input name="name" id="name" required></label><div class="split"><label>SKU<input name="sku" id="sku" required></label><label>Category<select name="category_id" id="category_id" required><?php foreach($categories as $category):?><option value="<?=e((string)$category['id'])?>"><?=e($category['name'])?></option><?php endforeach;?></select></label></div><label>Description<textarea name="short_description" id="short_description" required></textarea></label><div class="split"><label>Price (USD)<input type="number" name="price" id="price" step="0.01" min="0" required></label><label>Stock quantity<input type="number" name="stock_quantity" id="stock_quantity" min="0" required></label></div><div class="split"><label>Reorder level<input type="number" name="reorder_level" id="reorder_level" min="0" value="5" required></label><label>Status<select name="status" id="status"><option value="active">Active</option><option value="draft">Draft</option><option value="out_of_stock">Out of stock</option></select></label></div><label>Product photo<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label class="check"><input type="checkbox" name="featured" id="featured"> Feature on storefront</label><button>Save product</button></form><hr><h2>New category</h2><form method="post" class="category-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="category"><input name="category_name" placeholder="Category name" required><button>Add</button></form></section><section class="card products"><div class="table-title"><h2>All products</h2><span><?=count($products)?> products</span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th>State</th><th></th></tr></thead><tbody><?php foreach($products as $product):?><tr><td><div class="product-name"><?php if($product['image_path']):?><img src="../<?=e($product['image_path'])?>" alt=""><?php endif;?><div><b><?=e($product['name'])?></b><small><?=e($product['category_name'])?> · <?=e($product['sku'])?></small></div></div></td><td><?=money((float)$product['price'])?></td><td><b><?=e((string)$product['stock_quantity'])?></b><small>reorder <?=e((string)$product['reorder_level'])?></small></td><td><span class="state <?=e($product['status'])?>"><?=e($product['status'])?></span></td><td class="actions"><button type="button" class="edit" data-product='<?=e(json_encode($product,JSON_HEX_APOS|JSON_HEX_QUOT))?>'>Edit</button><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="deactivate"><input type="hidden" name="product_id" value="<?=e((string)$product['id'])?>"><button onclick="return confirm('Remove this product from the public store?')">Deactivate</button></form><form method="post" class="stock-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="stock"><input type="hidden" name="product_id" value="<?=e((string)$product['id'])?>"><input name="adjustment" type="number" placeholder="+/-" required><input name="note" placeholder="Reason"><button>Adjust</button></form></td></tr><?php endforeach;?></tbody></table></div></section></div></main><script>document.querySelectorAll('.edit').forEach(button=>button.addEventListener('click',()=>{const p=JSON.parse(button.dataset.product);for(const key of ['id','name','sku','category_id','short_description','price','stock_quantity','reorder_level','status']){const field=document.getElementById(key==='id'?'product_id':key);if(field)field.value=p[key]??'';}document.getElementById('featured').checked=Number(p.featured)===1;document.getElementById('product-form').scrollIntoView({behavior:'smooth'});}));</script></body></html>
